library;

class Remedy {
  /// What was dreamt (after "ถ้าฝันว่า").
  final String dream;

  /// The omen (after "ทายว่า").
  final String omen;

  /// How to undo it.
  final String cure;
  const Remedy(this.dream, this.omen, this.cure);
}

